#!/usr/bin/env python3
import os, sys, re, argparse, datetime, shutil
from pathlib import Path

VERSION='Terminal Todo List Manager(TTDL) Version 6.1.1'

def parse(line):
    from parser import parse_todo
    t=parse_todo(line)
    return {'raw':t.raw,'done':t.done,'pri':t.priority or '', 'created':t.created or '',
            'finished':t.completed or '', 'due':t.due or '', 'subject':t.subject,
            'projects':t.project,'contexts':t.context,'tags':t.tags,'completed':t.completed or ''}

def fmt(d,i,short=False):
    created='' if d['done'] else d['created']
    finished=d['finished'] or (d['created'] if d['done'] else '')
    return f"{i:2} {'x' if d['done'] else ' '} {d['pri']:1} {created:10} {finished:10} {d['due']:10} {d['subject']}"

def main():
    argv=sys.argv[1:]
    if '--version' in argv: print(VERSION); return 0
    if any(x in argv for x in ('-h','--help')):
        from helptext import show_help
        show_help(sys.argv[0]); return 0
    cmd='list'; commands={'list':'list','l':'list','add':'add','a':'add','done':'done','d':'done','undone':'undone','remove':'remove','rm':'remove','clean':'clean','archive':'clean','edit':'edit','e':'edit','append':'append','prepend':'prepend','listprojects':'listprojects','listproj':'listprojects','listcontexts':'listcontexts','listcon':'listcontexts','stats':'stats'}
    args=[]
    first_word=next((x for x in argv if not x.startswith('-')),None)
    unknown_as_add=bool(first_word and first_word not in commands and not first_word.startswith(('+','@')))
    for x in argv:
        if not x.startswith('-') and x in commands and cmd=='list' and not args: cmd=commands[x]
        else: args.append(x)
    path=Path(os.environ.get('TTDL_FILENAME','todo.txt'))
    if '--todo-file' in args:
        i=args.index('--todo-file'); path=Path(args[i+1]); del args[i:i+2]
    if '--local' in args: path=Path('todo.txt'); args.remove('--local')
    if path.is_dir(): path/= 'todo.txt'
    lines=path.read_text().splitlines() if path.exists() else []
    tasks=[parse(x) for x in lines]
    if cmd=='add' or unknown_as_add:
        subj=' '.join(x for x in args if not x.startswith('-'))
        if not subj.strip() or re.fullmatch(r'[+@]\S*',subj.strip()): print('Subject is empty'); return 1
        lines.append(subj.strip()); path.parent.mkdir(parents=True,exist_ok=True); path.write_text('\n'.join(lines)+'\n'); print('Added todo:'); print(' # D P Created    Finished   Due        Subject'); print('----------------------------------------------------------'); print(fmt(parse(lines[-1]),len(lines))); return 0
    if cmd in ('done','undone','remove','edit','append','prepend'):
        ids=[]
        for x in args:
            if re.fullmatch(r'\d+(?:[-,]\d+)*',x):
                for part in x.split(','):
                    ids.extend(range(*((lambda a,b:(a,b+1))(int(part.split('-')[0]),int(part.split('-')[-1])))))
        chosen=set(ids or range(1,len(lines)+1)); out=[]
        for i,line in enumerate(lines,1):
            d=parse(line)
            if i not in chosen: out.append(line); continue
            if cmd=='done' and not d['done']: line='x '+datetime.date.today().isoformat()+' '+line
            elif cmd=='undone' and d['done']: line=re.sub(r'^x\s+(?:\d{4}-\d\d-\d\d\s+)?','',line)
            elif cmd=='remove': continue
            elif cmd in ('append','prepend'):
                extra=' '.join(x for x in args if not re.fullmatch(r'\d+(?:[-,]\d+)*',x))
                line=(line+' '+extra) if cmd=='append' else (extra+' '+line)
            out.append(line)
        path.write_text(('\n'.join(out)+'\n') if out else '')
        if cmd=='remove': print(f'{len(lines)-len(out)} todo deleted' if len(lines)!=len(out) else 'No todo deleted')
        return 0
    if cmd=='listprojects' or cmd=='listcontexts':
        vals=set(v for d in tasks for v in d['projects' if cmd=='listprojects' else 'contexts'])
        print('\n'.join(sorted(vals))); return 0
    if cmd=='stats':
        done=sum(d['done'] for d in tasks); print(f'Total todos:          {len(tasks)}')
        if done: print(f'Done:                 {done} ({done*100//len(tasks)}%)')
        return 0
    if cmd=='list':
        inc=('-a' in args or '--all' in args or '-A' in args)
        inds=[(i,d) for i,d in enumerate(tasks,1) if inc or not d['done']]
        # Match the shared advanced tag filter when present.
        filt=next((x.split('=',1)[1] for x in args if x.startswith('--filter=') or x.startswith('-f=')),None)
        if filt:
            from filtering import matches_filter
            inds=[(i,d) for i,d in inds if matches_filter(d,filt)]
        if '--short' in args:
            print(' # D P Subject'); print('---------------')
            for i,d in inds: print(f" {i} {'x' if d['done'] else ' '} {d['pri']:1} {d['subject']}")
        else:
            print(' # D P Created    Finished   Due        Subject'); print('-------------------------------------------')
            for i,d in inds: print(fmt(d,i))
        if '-H' not in args and '--no-headers' not in args: print('-------------------------------------------'); print(f'{len(inds)} todos (of {len(tasks)} total)')
        return 0
    print('Unknown command'); return 1
if __name__=='__main__': sys.exit(main())

